steps.script:
var army: Dictionary = ArmyListManager.load_army_list("recon_stomps", 1)
if not army.get("units", {}).has("U_MEK_A"):
	return "recon_stomps has no U_MEK_A"
if GameState.state.units.has("U_MEK_A"):
	return "fixture already has a U_MEK_A"
var mek: Dictionary = army.units["U_MEK_A"].duplicate(true)
mek["owner"] = 1
mek["status"] = 2
mek["flags"] = {}
mek.models[0]["position"] = {"x": 1400.0, "y": 2065.0}
GameState.state.units["U_MEK_A"] = mek
var can: Dictionary = CharacterAttachmentManager.can_attach("U_MEK_A", "U_MEK_GUNZ_A")
if not can.get("valid", false):
	return "can_attach refused: %s" % str(can)
CharacterAttachmentManager.attach_character("U_MEK_A", "U_MEK_GUNZ_A")
GameState.state.units["U_MEK_GUNZ_A"].models[0]["position"] = {"x": 1400.0, "y": 1990.0}
var screen = GameState.state.units["U_CUSTODIAN_GUARD_C"].models
for i in range(screen.size()):
	screen[i]["position"] = {"x": 1334.0 + 66.0 * i, "y": 1850.0}
GameState.state.units["U_DEFF_DREAD_A"].models[0]["position"] = {"x": 1000.0, "y": 2150.0}
var kans = GameState.state.units["U_KILLA_KANS_A"].models
for i in range(kans.size()):
	kans[i]["position"] = {"x": 870.0 + 130.0 * i, "y": 2035.0}
var foes = GameState.state.units["U_CUSTODIAN_GUARD_D"].models
for i in range(foes.size()):
	foes[i]["position"] = {"x": 934.0 + 66.0 * i, "y": 2250.0}
tree.current_scene._recreate_unit_visuals()
var g: Dictionary = GameState.get_unit("U_MEK_GUNZ_A")
var m: Dictionary = GameState.get_unit("U_MEK_A")
if not "VEHICLE" in g.meta.keywords or "FLY" in g.meta.keywords or not "INFANTRY" in m.meta.keywords:
	return "not the case under test: %s / %s" % [str(g.meta.keywords), str(m.meta.keywords)]
return "%s attached to %s; %d Custodians in the lane; Deff Dread engaged=%s" % [str(m.get("attached_to")), "U_MEK_GUNZ_A" if g.attachment_data.attached_characters.has("U_MEK_A") else "?", screen.size(), str(RulesEngine.is_unit_engaged("U_DEFF_DREAD_A", GameState.state))]

var md: Dictionary = PhaseManager.get_current_phase_instance().active_moves.get("U_MEK_GUNZ_A", {})
var staged: Array = md.get("staged_moves", [])
if staged.size() != 1 or str(staged[0].get("model_source_unit_id", "")) != "U_MEK_GUNZ_A":
	var msgs := []
	for t in ToastManager.active_toasts:
		if is_instance_valid(t):
			for c in t.get_children():
				if c is Label:
					msgs.append(c.text)
	return "staged %d: %s" % [staged.size(), " | ".join(msgs)]
var dd = staged[0].get("dest")
var p := Vector2(float(dd[0]), float(dd[1])) if dd is Array else Vector2(dd.x, dd.y)
if p.distance_to(Vector2(1400.0, 1700.0)) > 3.0:
	return "staged at %s" % str(p)
return "only the Mek Gunz is staged, past the Custodians"

var msgs := []
for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		for c in t.get_children():
			if c is Label:
				msgs.append(c.text)
for msg in msgs:
	if "cannot follow" in msg:
		return "refused: " + msg
return "not refused: " + " | ".join(msgs)

var ph = PhaseManager.get_current_phase_instance()
var md: Dictionary = ph.active_moves.get("U_MEK_GUNZ_A", {})
var mek = GameState.state.units["U_MEK_A"].models[0].position
var gun = GameState.state.units["U_MEK_GUNZ_A"].models[0].position
return "open=%s staged=%d moved=%s mek=(%d,%d) gun=(%d,%d)" % [str(not md.get("completed", true)), md.get("staged_moves", []).size(), str(GameState.state.units["U_MEK_GUNZ_A"].get("flags", {}).get("moved", false)), int(round(float(mek.x))), int(round(float(mek.y))), int(round(float(gun.x))), int(round(float(gun.y)))]

var mek = GameState.state.units["U_MEK_A"].models[0].position
var gun = GameState.state.units["U_MEK_GUNZ_A"].models[0].position
var dg := Vector2(float(gun.x), float(gun.y)) - Vector2(1400.0, 1990.0)
var dm := Vector2(float(mek.x), float(mek.y)) - Vector2(1400.0, 2065.0)
if dg.distance_to(Vector2(-120.0, 90.0)) > 3.0:
	return "gun moved %s" % str(dg)
if dm.distance_to(dg) > 0.5:
	return "mek moved %s, gun %s" % [str(dm), str(dg)]
if RulesEngine.is_unit_engaged("U_MEK_A", GameState.state):
	return "mek engaged"
return "the Mek followed the Mek Gunz"

var md: Dictionary = PhaseManager.get_current_phase_instance().active_moves.get("U_DEFF_DREAD_A", {})
var staged: Array = md.get("staged_moves", [])
if staged.is_empty():
	var msgs := []
	for t in ToastManager.active_toasts:
		if is_instance_valid(t):
			for c in t.get_children():
				if c is Label:
					msgs.append(c.text)
	return "not staged — " + " | ".join(msgs)
var dd = staged[staged.size() - 1].get("dest")
var p := Vector2(float(dd[0]), float(dd[1])) if dd is Array else Vector2(dd.x, dd.y)
if p.distance_to(Vector2(1000.0, 1880.0)) > 3.0:
	return "staged at %s" % str(p)
return "staged past the Killa Kan"

var dr = GameState.state.units["U_DEFF_DREAD_A"].models[0]
var p := Vector2(float(dr.position.x), float(dr.position.y))
if p.distance_to(Vector2(1000.0, 1880.0)) > 3.0:
	return "Deff Dread at %s" % str(p)
var kans = GameState.state.units["U_KILLA_KANS_A"].models
for i in range(kans.size()):
	if Vector2(float(kans[i].position.x), float(kans[i].position.y)).distance_to(Vector2(870.0 + 130.0 * i, 2035.0)) > 0.5:
		return "a Killa Kan moved"
if RulesEngine.is_unit_engaged("U_DEFF_DREAD_A", GameState.state):
	return "ended engaged"
return "fell back through the Killa Kan, unengaged"
